-- golden: queries/union_of_sliced_parts
-- django: 6.0
-- profile: 7.5
-- depends: ddl/create_author, ddl/create_book
-- params: [[100, 100]]
-- verified: IBM i 7.5 on PUB400 (TR unknown, Db2 PTF Group unknown), Django 6.0.9, 2026-10-20
SELECT * FROM LATERAL ( (SELECT "TESTAPP_BOOK"."ID" AS "COL1", "TESTAPP_BOOK"."AUTHOR_ID" AS "COL2", "TESTAPP_BOOK"."TITLE" AS "COL3", "TESTAPP_BOOK"."PUBLISHED" AS "COL4", "TESTAPP_BOOK"."READING_TIME" AS "COL5", "TESTAPP_BOOK"."AVAILABLE" AS "COL6", "TESTAPP_BOOK"."PAGES" AS "COL7" FROM "TESTAPP_BOOK" WHERE "TESTAPP_BOOK"."PAGES" < %s ORDER BY "TESTAPP_BOOK"."PUBLISHED" DESC FETCH FIRST 2 ROWS ONLY) UNION (SELECT "TESTAPP_BOOK"."ID" AS "COL1", "TESTAPP_BOOK"."AUTHOR_ID" AS "COL2", "TESTAPP_BOOK"."TITLE" AS "COL3", "TESTAPP_BOOK"."PUBLISHED" AS "COL4", "TESTAPP_BOOK"."READING_TIME" AS "COL5", "TESTAPP_BOOK"."AVAILABLE" AS "COL6", "TESTAPP_BOOK"."PAGES" AS "COL7" FROM "TESTAPP_BOOK" WHERE "TESTAPP_BOOK"."PAGES" >= %s ORDER BY "TESTAPP_BOOK"."PUBLISHED" ASC OFFSET 1 ROWS FETCH FIRST 2 ROWS ONLY) ) ORDER BY "COL7" DESC;
